TYPE GateState : (IDLE, OPENING, CLOSING, FAULT) END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    currentState : GateState;
    prevOpenBtn : BOOL;
    prevCloseBtn : BOOL;
    openRising : BOOL;
    closeRising : BOOL;
END_VAR

// 边沿检测
openRising := openBtn AND NOT prevOpenBtn;
closeRising := closeBtn AND NOT prevCloseBtn;
prevOpenBtn := openBtn;
prevCloseBtn := closeBtn;

// 状态机
CASE currentState OF
    IDLE:
        motorUp := FALSE;
        motorDown := FALSE;
        errorFlag := FALSE;
        IF openRising AND NOT openLimit THEN
            currentState := OPENING;
        ELSIF closeRising AND NOT closeLimit THEN
            currentState := CLOSING;
        END_IF

    OPENING:
        motorUp := TRUE;
        motorDown := FALSE;
        IF obstacle THEN
            motorUp := FALSE;
            errorFlag := TRUE;
            currentState := FAULT;
        ELSIF openLimit THEN
            motorUp := FALSE;
            currentState := IDLE;
        END_IF

    CLOSING:
        motorUp := FALSE;
        motorDown := TRUE;
        IF obstacle THEN
            motorDown := FALSE;
            motorUp := TRUE;
            currentState := OPENING;
        ELSIF closeLimit THEN
            motorDown := FALSE;
            currentState := IDLE;
        END_IF

    FAULT:
        motorUp := FALSE;
        motorDown := FALSE;
        errorFlag := TRUE;
        IF openBtn AND closeBtn THEN
            errorFlag := FALSE;
            currentState := IDLE;
        END_IF
END_CASE

END_FUNCTION_BLOCK
